// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.codegen;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.junit.jupiter.api.Test;

/** Tests for the public date/inline primitives the fragment tier compiles against (fragment-fusion M0). */
class KernelRuntimeDateTest {

	private static long datePayload(int year, int month, int day, int tzField) {
		return (long) year | (long) month << 13 | (long) day << 17 | (long) tzField << 49;
	}

	private static long dateId(int year, int month, int day, int tzField) {
		return ValueIds.createId(ValueIds.T_DATE, datePayload(year, month, day, tzField));
	}

	@Test
	void packedKeyPreservesDateOrder() {
		int earlier = KernelRuntime.datePackedKey(datePayload(2023, 5, 14, 0));
		int sameDayLaterMonth = KernelRuntime.datePackedKey(datePayload(2023, 6, 14, 0));
		int nextYear = KernelRuntime.datePackedKey(datePayload(2024, 1, 1, 0));
		assertThat(earlier).isLessThan(sameDayLaterMonth);
		assertThat(sameDayLaterMonth).isLessThan(nextYear);
	}

	@Test
	void timezoneFieldRoundTrips() {
		assertThat(KernelRuntime.dateTimezoneField(datePayload(2023, 5, 14, 42))).isEqualTo(42);
		assertThat(KernelRuntime.dateTimezoneField(datePayload(2023, 5, 14, 0))).isZero();
	}

	@Test
	void dateSortKeyOrdersWithinTimezoneClass() {
		long may = KernelRuntime.dateSortKey(dateId(2023, 5, 14, 7));
		long june = KernelRuntime.dateSortKey(dateId(2023, 6, 1, 7));
		assertThat(may).isLessThan(june);
	}

	@Test
	void dateSortKeySeparatesTimezoneClasses() {
		long tzLow = KernelRuntime.dateSortKey(dateId(2023, 5, 14, 1));
		long tzHigh = KernelRuntime.dateSortKey(dateId(2020, 1, 1, 2));
		// different timezone classes land in disjoint key ranges regardless of date order
		assertThat(tzHigh).isGreaterThan(tzLow);
	}

	@Test
	void dateSortKeyEscapesNonDates() {
		assertThat(KernelRuntime.dateSortKey(-1L)).isEqualTo(KernelRuntime.SORT_KEY_ESCAPE);
		assertThat(KernelRuntime.dateSortKey(1L)).isEqualTo(KernelRuntime.SORT_KEY_ESCAPE); // inline double
		assertThat(KernelRuntime.dateSortKey(ValueIds.createId(ValueIds.T_URI, 5)))
				.isEqualTo(KernelRuntime.SORT_KEY_ESCAPE);
		assertThat(KernelRuntime.dateSortKey(
				ValueIds.createId(ValueIds.T_ORD_INTEGER, 12 + ValueIds.ORDERED_BIAS)))
						.isEqualTo(KernelRuntime.SORT_KEY_ESCAPE);
	}

	@Test
	void escapeSentinelIsOutsideEveryRealKeyRange() {
		// real keys are non-negative (7-bit tz << 32 | 22-bit packed date); the sentinel is Long.MIN_VALUE
		long smallest = KernelRuntime.dateSortKey(dateId(0, 1, 1, 0));
		assertThat(smallest).isGreaterThan(KernelRuntime.SORT_KEY_ESCAPE);
		assertThat(KernelRuntime.SORT_KEY_ESCAPE).isEqualTo(Long.MIN_VALUE);
	}

	@Test
	void packedKeyMatchesLegacyPrivateLayout() {
		// the historical dateKey layout: year<<9 | month<<5 | day
		long payload = datePayload(1999, 12, 31, 0);
		assertThat(KernelRuntime.datePackedKey(payload)).isEqualTo(1999 << 9 | 12 << 5 | 31);
	}
}
